import React, { useState } from 'react';
import { register, login } from '../services/api';

export default function Login({ onLogin }){
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [mode, setMode] = useState('login');
  const [err, setErr] = useState(null);

  async function submit(e){
    e.preventDefault();
    try{
      const res = mode==='login' ? await login(username,password) : await register(username,password);
      if (res.msg === 'ok'){
        onLogin(res.user || {username});
      } else { setErr(JSON.stringify(res)); }
    }catch(e){
      const msg = String(e);
      // convert generic fetch failure into something user-friendly
      if (msg.includes('NetworkError')) {
        setErr('Unable to reach the server. Please make sure the backend is running and try again.');
      } else {
        setErr(msg);
      }
    }
  }

  return (
    <div style={{display:'flex',justifyContent:'center',alignItems:'center',minHeight:'100vh',background:'#f0f4f8'}}>
      <form onSubmit={submit} style={{width:360,padding:40,background:'white',borderRadius:12,boxShadow:'0 2px 8px rgba(0,0,0,0.08)'}}>
        {/* FocusGuard Branding */}
        <div style={{textAlign:'center',marginBottom:28}}>
          <h1 style={{color:'#5a6c7d',margin:'0 0 4px 0',fontSize:28,fontWeight:600}}>FocusGuard</h1>
          <p style={{color:'#8a9aaa',margin:0,fontSize:13}}>Stay focused, stay aware</p>
        </div>

        {/* Form Title */}
        <h2 style={{textAlign:'center',marginBottom:28,color:'#5a6c7d',marginTop:0,fontSize:18}}>{mode==='login' ? 'Login' : 'Create Account'}</h2>

        {/* Username Field */}
        <div style={{marginBottom:16}}>
          <label style={{display:'block',marginBottom:8,fontWeight:500,color:'#6b7d8f',fontSize:13}}>Username</label>
          <input placeholder='Enter your username' value={username} onChange={e=>setUsername(e.target.value)} style={{margin:0,width:'100%',padding:'10px 12px',border:'1px solid #d4dce6',borderRadius:6,fontSize:14,color:'#3d4a57',fontFamily:'inherit'}} />
        </div>

        {/* Password Field */}
        <div style={{marginBottom:24}}>
          <label style={{display:'block',marginBottom:8,fontWeight:500,color:'#6b7d8f',fontSize:13}}>Password</label>
          <input placeholder='Enter your password' type='password' value={password} onChange={e=>setPassword(e.target.value)} style={{margin:0,width:'100%',padding:'10px 12px',border:'1px solid #d4dce6',borderRadius:6,fontSize:14,color:'#3d4a57',fontFamily:'inherit'}} />
        </div>

        {/* Submit Button */}
        <button type='submit' style={{width:'100%',padding:12,marginBottom:16,background:'#6b8cae',color:'white',border:'none',borderRadius:6,fontWeight:500,fontSize:15,cursor:'pointer',transition:'background 0.2s'}} onMouseEnter={e=>e.target.style.background='#5a7a97'} onMouseLeave={e=>e.target.style.background='#6b8cae'}>{mode==='login' ? 'Login' : 'Register'}</button>

        {/* Toggle Mode Button */}
        <div style={{textAlign:'center'}}>
          <button type='button' onClick={()=>setMode(mode==='login'?'register':'login')} style={{background:'none',color:'#6b8cae',padding:0,textDecoration:'none',fontWeight:500,cursor:'pointer',boxShadow:'none',fontSize:14,border:'none'}}>{mode==='login' ? 'Need an account? Sign up' : 'Already have an account? Login'}</button>
        </div>

        {/* Error Message */}
        {err && <div style={{color:'#a54836',marginTop:16,padding:12,backgroundColor:'#f5e6e3',borderRadius:6,fontSize:14,borderLeft:'3px solid #a54836'}}>{err}</div>}
      </form>
    </div>
  );
}
